private static <T> CompletableFuture<T> doQueryAsync(
        ElasticsearchEsqlAsyncClient client, EsqlAdapter<T> adapter, QueryRequest request
    ) {
        return client
            .query(request)
            .thenApply(r -> {
                try {
                    return adapter.deserialize(client, request, r);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            });
    }

